function resize(){const r=stage.getBoundingClientRect();camera.aspect=r.width/Math.max(1,r.height);camera.updateProjectionMatrix();renderer.setSize(r.width,r.height);graphics?.resize()}window.addEventListener('resize',resize);resize();
function draw(now){const rawDt=(now-previous)/1000||0,dt=Math.min(rawDt,1/30);previous=now;time+=dt;if(game&&state==='playing')game.update(dt);if(game?.ambient)game.ambient(dt);pressed.clear();graphics.render(rawDt);frame=requestAnimationFrame(draw)}frame=requestAnimationFrame(draw);
ctx.graphics=graphics;const loader=new GLTFLoader(),loadModel=url=>loader.loadAsync(graphics.modelURL(url)).catch(()=>loader.loadAsync(url));Promise.all([loadModel('models/hero.glb'),...Object.entries(config.models||{}).map(async([name,url])=>[name,(await loadModel(url)).scene])]).then(([asset,...variants])=>{ctx.models=Object.fromEntries(variants);game=create(ctx,asset.scene);graphics.decorate();state='ready';$('#load-status').textContent='PBR model ready · keyboard, mouse & touch';$('#start-game').disabled=false;$('#start-game').textContent='Let’s play →';$('#start-game').focus();if(new URLSearchParams(location.search).get('build')==='1'){$('#build-panel').hidden=false;$('#build-close').focus()}}).catch(error=>{$('#load-status').textContent='A 3D asset could not load. Reload to try again.';console.error(error)});

window.addEventListener('keydown',e=>{if(e.target.closest('input,select,textarea'))return;if(e.code==='Escape'||e.code==='KeyP'){e.preventDefault();if(!$('#build-panel').hidden){$('#build-panel').hidden=true;return}pause();return}if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code)&&state==='playing')e.preventDefault();if(state==='playing'){if(!keys.has(e.code))pressed.add(e.code);keys.add(e.code)}});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();pressed.clear();if(state==='playing')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='playing')pause()});
const touch=$('#touch-controls'),touches=new Map();touch.innerHTML=config.touch.map(([code,label])=>`<button data-key="${code}" aria-label="${label}">${label}</button>`).join('');touch.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-key]');if(!b||state!=='playing')return;e.preventDefault();b.setPointerCapture(e.pointerId);touches.set(e.pointerId,b);if(!keys.has(b.dataset.key))pressed.add(b.dataset.key);keys.add(b.dataset.key);b.classList.add('held')});const up=e=>{const b=touches.get(e.pointerId);if(!b)return;touches.delete(e.pointerId);if(![...touches.values()].includes(b)){keys.delete(b.dataset.key);b.classList.remove('held')}};for(const event of ['pointerup','pointercancel','lostpointercapture'])touch.addEventListener(event,up);window.addEventListener('blur',()=>{touches.clear();touch.querySelectorAll('.held').forEach(b=>b.classList.remove('held'))});window.visualViewport?.addEventListener('resize',resize);

$('#start-game').onclick=start;$('#restart').onclick=start;$('#pause-button').onclick=pause;$('#resume').onclick=pause;$('#pause-restart').onclick=start;$('#change-mode').onclick=()=>{state='ready';$('#pause-panel').hidden=true;$('#end-panel').hidden=true;$('#start-panel').hidden=false};const showBuild=()=>{if(state==='playing')pause();$('#build-panel').hidden=false;$('#build-close').focus()};$('#build-button').onclick=showBuild;document.querySelectorAll('[data-build]').forEach(b=>b.onclick=showBuild);$('#build-close').onclick=()=>$('#build-panel').hidden=true;$('#sound-button').onclick=()=>{sound=!sound;$('#sound-button').textContent=sound?'Sound on':'Sound off';if(sound)tone()};$('#fullscreen-button').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>announce('Fullscreen is unavailable in this browser.'))};$('#return-button').onclick=()=>{if(history.length>1)history.back();else location.href='../../games.html'};
